import math

alpha = math.sqrt(2)

def calculate_E(m, n, alpha):
    # Simplified expression: E = m + m*floor(n*alpha) - n*floor(m*alpha)
    # We rely on alpha being irrational, so ceil(x) = floor(x) + 1

    # Check the original form for verification
    E_original = m * math.ceil(n * alpha) - n * math.floor(m * alpha)

    # Check the simplified form
    E_simplified = m + m * math.floor(n * alpha) - n * math.floor(m * alpha)

    # If they match, return the value
    if abs(E_original - E_simplified) < 1e-9:
        return int(round(E_original))
    else:
        return "MISMATCH"

pairs = [
    (1, 1), (1, 2), (2, 1), (2, 2), (1, 3), (3, 1),
    (2, 3), (3, 2), (1, 4), (4, 1)
]

results = {}
for m, n in pairs:
    results[(m, n)] = calculate_E(m, n, alpha)

print("E(m, n, sqrt(2)):")
for pair, value in results.items():
    print(f"({pair[0]}, {pair[1]}): {value}")

